class DiseaseProcess:
    def __init__(self, base_transmission_rate: float, incubation_mean: float, infectious_mean: float,
                 mask_inward_efficacy: float, mask_outward_efficacy: float, contact_modifiers: Dict[str, float]):
        self.beta = base_transmission_rate
        self.incubation_mean = incubation_mean
        self.infectious_mean = infectious_mean
        self.mask_inward = mask_inward_efficacy
        self.mask_outward = mask_outward_efficacy
        self.contact_modifiers = contact_modifiers
        self.states = {"S": set(), "E": set(), "I": set(), "R": set()}
        self.new_infections_daily: List[int] = []
    def transmit_given_contact(self, src_masked: bool, dst_masked: bool, location_type: str) -> float:
        m_out = (1.0 - self.mask_outward) if src_masked else 1.0
        m_in = (1.0 - self.mask_inward) if dst_masked else 1.0
        loc = self.contact_modifiers.get(location_type, 1.0)
        return self.beta * m_out * m_in * loc
